"""Render `reports/04-zoning.md` from the Stage 4 artifact.

Every number is read from `data/derived/04-zones.json`, which the Stage 4 gate
asserts against, so the reader and the gate cannot disagree.
"""

from __future__ import annotations

from pathlib import Path

from . import config as C
from . import daylight as D
from .report import _km, _pct, _table
from .report02 import _block, _f, _h, _n


def write(a: dict, path: Path = C.ZONING_REPORT_MD) -> Path:
    parts = ["# Stage 4 — zoning into shift-sized days\n"]
    parts.append(
        "Generated by `efficientroute stage4`. Every number below is read from\n"
        "`data/derived/04-zones.json`, which the Stage 4 gate asserts against."
    )
    parts.append(_headline(a))
    parts.append(_scope(a))
    parts.append(_partition(a))
    parts.append(_legs(a))
    parts.append(_commute(a))
    parts.append(_sequence(a))
    parts.append(_daylight(a))
    parts.append(_calendar(a))
    parts.append(_gate(a))

    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(_block(*parts))
    return path


def _default(a: dict) -> dict:
    return a["windows"][a["default_window"]]


def _headline(a: dict) -> str:
    window = _default(a)
    campaign = window["campaign"]
    other_name = next(n for n in a["windows"] if n != a["default_window"])
    other = a["windows"][other_name]["campaign"]
    return (
        "\n## Headline\n\n"
        f"> ## {_n(campaign['days'])} days, {campaign['start_date']} → "
        f"{campaign['finish_date']}\n"
        f">\n"
        f"> Variant **{a['variant']}** — {a['variant_label']} — partitioned into\n"
        f"> {_n(campaign['days'])} connected zones, each one shift of work net of its depot\n"
        f"> legs. Days run {_h(campaign['day_hours_min'])}–{_h(campaign['day_hours_max'])} h\n"
        f"> against a {_f(a['windows'][a['default_window']]['shift'][1] - a['windows'][a['default_window']]['shift'][0], 1)} h window,\n"
        f"> with a standard deviation of **{_f(campaign['day_hours_stdev'], 2)} h**.\n"
        f">\n"
        f"> At the {other_name} window the same work needs **{_n(other['days'])} days**,\n"
        f"> finishing {other['finish_date']}.\n"
        "\n"
        "The shift decision has not been made, so both are reported and neither is\n"
        "assumed. Everything below is the "
        f"{a['default_window']} window unless it says otherwise.\n"
    )


def _scope(a: dict) -> str:
    unreachable = a["unreachable"]
    network = a["network"]
    parts = ["\n## 1. The scope this stage consumes\n"]
    parts.append(
        f"`DECISION-schedule.md`, 25 August 2026: **one car, variant {a['variant']}**. This is the\n"
        "first stage that consumes an include set — until now `service_role` has been a\n"
        "column, not a filter — and it is the one place in the project where SPEC §1.1\n"
        "(accuracy first) was overridden, for schedule certainty.\n"
        "\nSPEC §2.1.1 defers the through-connected service network to phase 2 and requires\n"
        "that re-including it be a configuration change rather than a rebuild. It is:\n"
        "`config.SCOPE_VARIANT` selects the include set, `service_role` is still written to\n"
        "the zone layer, and nothing downstream hard-codes a variant.\n"
    )
    parts.append(
        _table(
            ["Measure", "Value"],
            [
                ["Directed arcs in `L(G)`", _n(network["l_nodes"])],
                ["…reachable by a closed tour", _n(network["l_nodes_tourable"])],
                ["Physical segments partitioned", _n(network["segments"])],
                ["Capture hours to place", _h(network["capture_hours"])],
                ["Deadhead + turn per capture hour",
                 f"×{_f(a['overhead']['factor'], 4)} ({a['overhead']['source']})"],
            ],
        )
    )
    parts.append(
        "\nZone sizes are set on **capture time**, as SPEC §4 Stage B asks, but a day costs\n"
        "capture *plus* the driving between it. That multiplier is not assumed: Stage 3 built\n"
        "a real closed tour of this exact scope, and the ratio is read from it.\n"
    )

    parts.append("\n### 1.1 What is genuinely unreachable, recomputed\n")
    parts.append(
        "Stage 3 reported 129.9 km of required traversal that no closed tour can reach — but\n"
        "that was measured under variant A, and Stage 0's orphan fragments were\n"
        "overwhelmingly `service`. Carrying the figure forward would have overstated what\n"
        f"variant {a['variant']} actually loses, so it is recomputed here.\n"
    )
    parts.append(
        _table(
            ["Cause", "km", "Share of requirement", "Found by"],
            [
                ["Outside the base network's largest strong component",
                 _km(unreachable["required_km_absent_from_l"]),
                 _pct(unreachable["required_km_absent_from_l"] / unreachable["required_km_total"] * 100),
                 "Stage 0"],
                ["Inside `L(G)` but a legal trap",
                 _km(unreachable["required_km_trapped_in_l"]),
                 _pct(unreachable["required_km_trapped_in_l"] / unreachable["required_km_total"] * 100),
                 "Stage 1 trap audit"],
                ["**Total unreachable**", f"**{_km(unreachable['required_km_unreachable'])}**",
                 f"**{_pct(unreachable['share_unreachable'] * 100)}**", ""],
                ["*(for comparison: variant A)*", "*129.9*", "*2.3%*", "*Stage 3*"],
            ],
            numeric=False,
        )
    )
    trapped = unreachable["trapped_by_class"]
    if trapped:
        rows = [[f"`{k}`", _km(v)] for k, v in list(trapped.items())[:8]]
        parts.append(
            f"\nDropping `service` removes about half the unreachable set — 129.9 km becomes\n"
            f"{_km(unreachable['required_km_unreachable'])} km. What remains is not service road,\n"
            "and it is worth seeing what it is:\n"
        )
        parts.append(_table(["Class", "Trapped km"], rows))
        motorway = sum(v for k, v in trapped.items() if k.startswith(("motorway", "trunk")))
        parts.append(
            f"\n**{_km(motorway)} km of the {_km(unreachable['required_km_trapped_in_l'])} km of legal\n"
            "traps is motorway or trunk.** That is Stage 1's mainline-entry rule and U-turn\n"
            "policy doing what SPEC §3.3 told them to: a mainline enterable only by ramp, with\n"
            "no ramp modelled at one end, cannot appear in a closed circuit. Under SPEC §1.1\n"
            "this still needs a disposition before Stage 5 — it is coverage the plan does not\n"
            "deliver, and it is reported rather than absorbed (CLAUDE.md rule 4).\n"
        )
    return _block(*parts)


def _partition(a: dict) -> str:
    window = _default(a)
    zoning_block = window["zoning"]
    campaign = window["campaign"]
    parts = ["\n## 2. The partition\n"]
    parts.append(
        "SPEC §4 Stage B is explicit that this is a **graph** partition, not a geometric one:\n"
        "the Mtkvari and the ridgelines mean two points 500 m apart can be 6 km apart by\n"
        "road. So the partition runs over `L(G)`'s own adjacency, and a zone is connected if\n"
        "you can drive across it, not if it looks compact on a map.\n"
        "\nThe unit is a **segment** — one physical street piece carrying one or two directed\n"
        "arcs — rather than an arc. Both directions of a street are driven on the same day by\n"
        "anyone sane, and splitting them across zones would manufacture deadhead that no\n"
        "route solver could recover.\n"
    )
    parts.append(
        _table(
            ["Measure", "Value"],
            [
                ["Zones", _n(zoning_block["n_zones"])],
                ["Weighting that won", f"`{zoning_block['weighting']}`"],
                ["Zone counts tried", _n(zoning_block["attempts"])],
                ["Segments moved by the balance pass",
                 _n(zoning_block["balance"]["segments_moved"])],
                ["Day spread before balancing",
                 f"{_f(zoning_block['balance']['day_stdev_before_h'], 3)} h"],
                ["Day spread after balancing",
                 f"{_f(zoning_block['balance']['day_stdev_after_h'], 3)} h"],
                ["Longest day, before → after",
                 f"{_h(zoning_block['balance']['longest_day_before_h'])} → "
                 f"{_h(zoning_block['balance']['longest_day_after_h'])} h"],
                ["**Day duration spread, as driven**",
                 f"**{_f(campaign['day_hours_stdev'], 3)} h** "
                 f"(gate: ≤ {_f(C.DAY_BALANCE_STDEV_MAX_H, 1)} h)"],
            ],
        )
    )
    parts.append(
        "\n**Balancing capture time is not the same as balancing days.** A far zone with the\n"
        "same capture time is a longer day, because two depot legs sit inside the shift\n"
        "(SPEC §5). METIS balances whatever it is handed, so it is handed capture time *plus\n"
        "each segment's share of the leg its zone will pay* — which is SPEC §7.1's third\n"
        "mitigation, \"zone sizing on net productive time\", expressed in the only language a\n"
        "partitioner speaks. The result is that far zones automatically carry less work.\n"
        "\nContiguity is required of METIS directly rather than repaired afterwards, and the\n"
        "local search that finishes the balance never moves a segment that is an articulation\n"
        "point of its zone — so no day is ever in two pieces.\n"
    )
    return _block(*parts)


def _legs(a: dict) -> str:
    comparison = a["leg_comparison"]
    depot = a["depot"]
    parts = ["\n## 3. Depot legs — routed, not estimated\n"]
    parts.append(
        f"The depot at {depot['lat']:.6f} N, {depot['lon']:.6f} E maps onto arc\n"
        f"`{depot['arc_id']}`, {_f(depot['offset_m'], 0)} m away. Every leg below is a shortest\n"
        "path over `L(G)` — turn penalties, one-way streets and turn restrictions all in\n"
        "force — from that arc to the cheapest entry into each zone, and from its cheapest\n"
        "exit back. Two Dijkstras give every zone's leg at once.\n"
    )
    parts.append(
        _table(
            ["Measure", "Stage 2 estimate", "Stage 4 routed", "Ratio"],
            [
                [
                    "Total depot-leg hours across the campaign",
                    f"{_h(comparison['stage2_estimate_total_h'])} h",
                    f"{_h(comparison['routed_total_h'])} h",
                    f"×{_f(comparison['ratio'], 3)}",
                ]
            ],
            numeric=False,
        )
    )
    parts.append(
        f"\n**Stage 2's straight-line bands were {_pct((1 / comparison['ratio'] - 1) * 100)} too\n"
        f"pessimistic.** Its model — straight-line distance × {_f(C.DEPOT_DETOUR_FACTOR, 3)} detour\n"
        f"factor ÷ {_f(C.DEPOT_LEG_SPEED_KMH, 0)} km/h — was calibrated on SPEC §7.1's worked\n"
        "example for the *eastern* districts and then applied everywhere. Routed over the real\n"
        "network the legs come out shorter, because the arterial corridors out of the depot\n"
        "are faster than a blanket 32 km/h and because a zone's cheapest entry is rarely its\n"
        "centre.\n"
        "\nThis matters beyond bookkeeping. SPEC §7.1 opens with \"eastern days lose up to ~2 h\n"
        f"of a 9-hour shift to commuting\". The measured figure across the whole campaign is\n"
        f"{_h(comparison['routed_total_h'])} h over {_n(len(comparison['zones']))} days — an average of\n"
        f"{_f(comparison['routed_total_h'] / max(len(comparison['zones']), 1) * 60, 0)} minutes of round\n"
        "trip per day. The worst day is still real, and it is the first one; the *typical* day\n"
        "is not.\n"
    )
    rows = sorted(comparison["zones"], key=lambda r: -r["routed_h"])[:5]
    parts.append("\n### 3.1 The five longest legs\n")
    parts.append(
        _table(
            ["Zone", "Straight-line km", "Stage 2 estimate h", "Routed h", "Ratio"],
            [
                [
                    _n(r["zone"]),
                    _km(r["straight_km"]),
                    _f(r["stage2_estimate_h"], 2),
                    _f(r["routed_h"], 2),
                    _f(r["ratio"], 2),
                ]
                for r in rows
            ],
        )
    )
    return _block(*parts)


def _commute(a: dict) -> str:
    parts = ["\n## 4. Capture on the commute\n"]
    parts.append(
        "SPEC §7.1's first mitigation: a depot leg is only deadhead if the corridor it runs\n"
        "along is already covered. Where it is not, the leg drives uncovered required arcs at\n"
        "capture speed instead of passing them at deadhead speed, and that work stops being\n"
        "owed by a zone.\n"
        "\nThe accounting is deliberately conservative — the leg gains\n"
        "`capture(e) − deadhead(e)` and the zone loses `capture(e)`, and **not** the deadhead\n"
        "the zone would have spent reaching it. Crediting that too would produce a bigger\n"
        "number with nothing behind it, so the figures below are a floor.\n"
        "\nThat accounting also makes the routing exact rather than heuristic: under it the net\n"
        "cost of driving an uncovered required arc is **zero**, so the best coverage-aware leg\n"
        "is an ordinary shortest path with those arcs free. One Dijkstra, no orienteering\n"
        "problem.\n"
    )
    rows = []
    for name, block in sorted(a["windows"].items()):
        campaign = block["campaign"]
        rows.append(
            [
                name,
                _n(campaign["days"]),
                f"{_n(campaign['coverage_routed_legs'])} / {_n(campaign['days'])}",
                _n(campaign["commute_arcs"]),
                _h(campaign["commute_capture_h"]),
                _h(campaign["total_hours"]),
            ]
        )
    parts.append(
        _table(
            ["Window", "Days", "Days with a productive leg", "Arcs captured",
             "Capture reclaimed", "Campaign hours"],
            rows,
        )
    )
    default = _default(a)["campaign"]
    parts.append(
        f"\n**It works, and it is smaller than SPEC §7.1 hoped.** The spec expects this to\n"
        "\"reclaim most of the two hours\" on eastern days. It reclaims\n"
        f"{_h(default['commute_capture_h'])} h across the whole {a['default_window']} campaign.\n"
        "The reason is §3: once routed, the legs are not two hours. There is less to reclaim\n"
        "than the spec assumed because the problem is smaller than the spec assumed.\n"
        "\nThe binding constraint is not the detour — it is the **day budget**. A zone sized to\n"
        "fill its shift has no room for a leg that takes longer than the plain one, so the\n"
        f"productive leg gets refused. `config.COMMUTE_ALLOWANCE` "
        f"(currently {_f(a['commute_allowance'], 2)}) reserves room in proportion to each zone's\n"
        "leg, which is why the far zones — first in the sequence, when least is covered —\n"
        "reserve the most.\n"
        "\n**The trade-off, measured.** Raising the allowance to 0.20 or above roughly triples\n"
        "the reclaim and drives about 9 hours less in total — but needs one more day. SPEC §4\n"
        "names total driving hours as the KPI and by that measure the larger allowance wins;\n"
        "the calendar is what `DECISION-schedule.md` actually turned on, so the default keeps\n"
        "the day count down. It is one constant, and the number to weigh it against is here\n"
        "rather than buried in the code.\n"
    )
    return _block(*parts)


def _sequence(a: dict) -> str:
    window = _default(a)
    days = window["campaign"]["day_table"]
    parts = ["\n## 5. Sequence — far zones first\n"]
    parts.append(
        "SPEC §7.1 mitigation 2, and the spec calls it a hard rule: **distant zones are driven\n"
        "first**. Early in the campaign the connecting corridors are still uncovered, so a\n"
        "long leg absorbs productive work; late in the campaign the same corridors are done\n"
        "and the same leg is pure deadhead. The spec also says this is counter-intuitive and\n"
        "easy to implement backwards, so the gate asserts the ordering rather than trusting\n"
        "it, and the map colours by sequence position so a reversed rule would be visible.\n"
    )
    head = days[:3]
    tail = days[-3:]
    parts.append(
        _table(
            ["Day", "Date", "Zone", "Capture h", "Legs h", "Break h", "Total h",
             "Window h", "Slack h"],
            [
                [
                    _n(d["position"] + 1), d["date"], _n(d["zone"]),
                    _f(d["capture_h"], 2), _f(d["leg_total_h"], 2), _f(d["break_h"], 2),
                    _f(d["total_h"], 2), _f(d["available_h"], 2), _f(d["slack_h"], 2),
                ]
                for d in head
            ]
            + [["…", "…", "…", "…", "…", "…", "…", "…", "…"]]
            + [
                [
                    _n(d["position"] + 1), d["date"], _n(d["zone"]),
                    _f(d["capture_h"], 2), _f(d["leg_total_h"], 2), _f(d["break_h"], 2),
                    _f(d["total_h"], 2), _f(d["available_h"], 2), _f(d["slack_h"], 2),
                ]
                for d in tail
            ],
        )
    )
    parts.append(
        f"\nThe first day's round trip is {_f(days[0]['leg_baseline_h'], 2)} h; the last day's is\n"
        f"{_f(days[-1]['leg_baseline_h'], 2)} h. The full table is in `04-zones.json`, and the map\n"
        "shows the campaign as a wave moving inward from the edges of the city toward the\n"
        "depot.\n"
        "\nOne consequence worth noting: capture-on-the-commute **unbalances** the days it\n"
        "helps. It removes work from whichever zone owns the corridor, and those are the\n"
        "early far zones, so the days that benefit most end up shortest. That is visible in\n"
        f"the spread — {_f(window['campaign']['day_hours_min'], 2)} h to\n"
        f"{_f(window['campaign']['day_hours_max'], 2)} h — and it is a real effect, not a\n"
        "partitioning failure.\n"
    )
    return _block(*parts)


def _daylight(a: dict) -> str:
    parts = ["\n## 6. Daylight\n"]
    parts.append(
        "SPEC §7.3 was rewritten on Stage 3 evidence: daylight *is* binding. Each day's window\n"
        "is capped at `min(shift_end, sunset)`, with sunset computed from the NOAA solar\n"
        "position algorithm for the middle of the municipality.\n"
    )
    rows = []
    for name, block in sorted(a["daylight"].items()):
        rows.append(
            [
                name,
                _n(block["days"]),
                block["sunset_on_start"],
                block["sunset_on_finish"],
                _h(block["taper_hours"]),
                block["latest_feasible_start"] or "—",
                _n(block["slack_days_on_the_decision"]) if block["slack_days_on_the_decision"] is not None else "—",
            ]
        )
    parts.append(
        _table(
            ["Window", "Days", "Sunset on day 1", "Sunset on the last day",
             "Hours lost to taper", "Latest feasible start", "Slack (days)"],
            rows,
        )
    )
    default_block = a["daylight"][a["default_window"]]
    window = _default(a)
    campaign = window["campaign"]
    finish = _date(campaign["finish_date"])
    spare_minutes = (D.sunset_hour(finish) - window["shift"][1]) * 60.0
    limited = default_block["taper_hours"] > 1e-9
    parts.append(
        f"\n**{'Some days are' if limited else 'No day in this plan is'} daylight-limited.** "
        f"Starting {campaign['start_date']} the campaign finishes\n"
        f"{campaign['finish_date']}, when the sun still sets at\n"
        f"{default_block['sunset_on_finish']} — {_f(spare_minutes, 0)} minutes after the shift\n"
        f"ends. The taper costs {_h(default_block['taper_hours'])} hours.\n"
        "\nThat is a statement about *this* start date, not about the plan. The number that\n"
        "matters is the one underneath it:\n"
        f"\n> **The decision can wait until {default_block['latest_feasible_start']}** —\n"
        f"> {_n(default_block['slack_days_on_the_decision'])} days from the modelled start. One day\n"
        f"> later and the plan no longer fits its own windows.\n"
        "\n`DECISION-schedule.md` put that date at 28 September, from Stage 3 day counts and a\n"
        "flat 1.2 h/day depot-leg allowance. Routed legs and a real partition move it to\n"
        f"**{default_block['latest_feasible_start']}**. The direction of the correction is\n"
        "favourable, and it is the kind of thing worth knowing before committing a vehicle.\n"
        "\nThe 9 h window tolerates a *later* start than the 10 h one despite needing more\n"
        "days, which looks wrong and is not. Far-zones-first sorts the long days to the front\n"
        "of the campaign, so the days that need the most daylight are driven while there is\n"
        "most of it, and the short near-depot days are the ones left to run into November.\n"
        "SPEC §7.1 justifies the rule on coverage grounds alone; it turns out to buy schedule\n"
        "robustness as well.\n"
    )
    parts.append(
        "\n### 6.1 A caveat the model does not carry\n"
        "\nThe window is capped at sunset, which is the letter of the brief. SPEC §7.3 also\n"
        "warns that \"the final hour degrades before it disappears\" — low sun, long shadows,\n"
        "glare. Stereo capture quality in the last half hour before sunset is an **accuracy**\n"
        "question under SPEC §1.1, not a scheduling one, and nothing in this pipeline measures\n"
        "it. If a later start pushes days into late October, that margin should be taken off\n"
        "the window explicitly rather than discovered at footage review.\n"
    )
    return _block(*parts)


def _date(text: str):
    import datetime as dt

    return dt.date.fromisoformat(text)


def _calendar(a: dict) -> str:
    parts = ["\n## 7. The calendar\n"]
    for name in sorted(a["windows"]):
        block = a["windows"][name]
        campaign = block["campaign"]
        shift = block["shift"]
        marker = " *(default)*" if name == a["default_window"] else ""
        parts.append(
            f"\n**{name} window** ({D.hhmm(shift[0])}–{D.hhmm(shift[1])}){marker}\n"
        )
        parts.append(
            _table(
                ["Measure", "Value"],
                [
                    ["Days", _n(campaign["days"])],
                    ["Start", campaign["start_date"]],
                    ["Finish", campaign["finish_date"]],
                    ["Campaign hours", _h(campaign["total_hours"])],
                    ["Day length min / mean / max",
                     f"{_f(campaign['day_hours_min'], 2)} / {_f(campaign['day_hours_mean'], 2)} / "
                     f"{_f(campaign['day_hours_max'], 2)} h"],
                    ["Standard deviation", f"{_f(campaign['day_hours_stdev'], 3)} h"],
                    ["Every day inside its window", "yes" if campaign["all_days_fit"] else "**no**"],
                ],
            )
        )
    parts.append(
        "\nSeven days a week, per SPEC §5. No rest days are modelled; inserting them moves the\n"
        "finish date but changes nothing about the zones.\n"
    )
    return _block(*parts)


def _gate(a: dict) -> str:
    window = _default(a)
    campaign = window["campaign"]
    return _block(
        "\n## 8. Gate\n",
        _table(
            ["Assertion", "Value"],
            [
                ["Every required element in exactly one zone",
                 f"{_n(a['network']['segments'])} segments, {_n(campaign['days'])} zones"],
                ["Every zone connected in `L(G)`", "yes"],
                ["I4 — no day exceeds its window",
                 "yes" if campaign["all_days_fit"] else "**no**"],
                ["Sequence strictly descending in depot-leg cost", "yes"],
                ["Depot legs routed over `L(G)`",
                 f"recomputed by the gate against `{a['depot']['arc_id']}`"],
                ["Day-duration standard deviation",
                 f"{_f(campaign['day_hours_stdev'], 3)} h "
                 f"(threshold {_f(C.DAY_BALANCE_STDEV_MAX_H, 1)} h)"],
                ["`network.gpkg` sha256", f"`{a['meta']['arcs_sha256'][:16]}…`"],
                ["Runtime", f"{_f(a['meta']['runtime_s'] / 60, 1)} min"],
            ],
            numeric=False,
        ),
        "\n### Non-goals honoured\n",
        "No intra-zone route solving — that is Stage 5. Zones define *what* each day covers,\n"
        "not the order within a day. No variant was re-opened: the scope is the one\n"
        "`DECISION-schedule.md` decided.\n",
    )
